def organize_books(books):
    books_by_author = {}
    for book in books:
        parts = book.split('/')
        author = parts[0].replace('-', ' ')
        title = parts[1]

        if author in books_by_author:
            books_by_author[author].append(title)
        else:
            books_by_author[author] = [title]

    return books_by_author

