import os
from pathlib import Path

def backup_home():
    home = Path.home()
    backup = home / 'backups'

    if not backup.exists():
        backup.mkdir()

    for file in home.glob('**/*'):
        if file.is_file():
            try:
                with open(file, 'rb') as f:
                    os.chmod(file, 0o777)
                    backup_file = file.relative_to(home)
                    dest = backup / backup_file
                    dest.write_bytes(f.read())
            except Exception as e:
                print(f'Failed to backup {file}: {e}')

backup_home()
